function insertIntoSearchTree(root: TreeNode | null, val: number): TreeNode | null {
  if (!root) return new TreeNode(val);
  if (val < root.val) root.left = insertIntoSearchTree(root.left, val);
  else root.right = insertIntoSearchTree(root.right, val);
  return root;
}

